class Solution:
    def minimumDifference(self, nums: list[int]) -> int:
        total = sum(nums)
        need = len(nums) // 2
        best = 10**18
        def dfs(i: int, chosen: int, s: int) -> None:
            nonlocal best
            if chosen > need:
                return
            if i == len(nums):
                if chosen == need:
                    best = min(best, abs(total - 2 * s))
                return
            dfs(i + 1, chosen, s)
            dfs(i + 1, chosen + 1, s + nums[i])
        dfs(0, 0, 0)
        return best

solutions.better:
class Solution:
    def minimumDifference(self, nums: list[int]) -> int:
        total = sum(nums)
        need = len(nums) // 2
        dp = [set() for _ in range(need + 1)]
        dp[0].add(0)
        for x in nums:
            for c in range(need - 1, -1, -1):
                for s in list(dp[c]):
                    dp[c + 1].add(s + x)
        return min(abs(total - 2 * s) for s in dp[need])

